package br.com.admeclesial.interfaces.rest.financeiro; import br.com.admeclesial.application.financeiro.*; import br.com.admeclesial.domain.financeiro.TransferenciaFinanceira; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/transferencias-financeiras") public class TransferenciaFinanceiraRestController { final TransferenciaFinanceiraApplicationService s; public TransferenciaFinanceiraRestController(TransferenciaFinanceiraApplicationService s){this.s=s;} @PostMapping public ResponseEntity<TransferenciaFinanceira> criar(@Valid @RequestBody TransferenciaFinanceiraRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.criar(r));} @GetMapping public List<TransferenciaFinanceira> listar(){return s.listar();} }
